def clean_scores(records):
    valid = []
    for name, raw in records:
        try:
            score = int(str(raw).strip())
        except ValueError:
            continue
        if 0 <= score <= 100:
            valid.append((name, score))
    valid.sort(key=lambda x: (-x[1], x[0]))
    return [name for name, _ in valid]

