class DiscountItem(Item):
    def __init__(self, name, price, rate):
        super().__init__(name, price)
        self.rate = rate
    def final_price(self):
        return (self.price * (100 - self.rate)) // 100

def calc_discounted(price, rate):
    return DiscountItem("상품", price, rate).final_price()

