from collections import Counter

def solution(logs, banned):
    ban = {b.lower() for b in banned}
    counts = Counter()
    for line in logs:
        _, body = line.split(":", 1)
        for word in body.lower().split():
            if word not in ban:
                counts[word] += 1
    ordered = sorted(counts.items(), key=lambda x: (-x[1], x[0]))
    return [word for word, _ in ordered[:2]]

