questions.solution:
class Account:
    def __init__(self, balance):
        self.balance = balance
    def deposit(self, n):
        self.balance += n
    def withdraw(self, n):
        if n > self.balance:
            raise ValueError("잔액 부족")
        self.balance -= n

def simulate(start, actions):
    account = Account(start)
    for n in actions:
        try:
            if n >= 0:
                account.deposit(n)
            else:
                account.withdraw(-n)
        except ValueError:
            continue
    return account.balance

print(simulate(100, [50, -300, -20]))

