def hidden_roots(lines):
    result = []
    for line in lines:
        fields = line.split(":")
        if fields[2] == "0" and fields[0] != "root":
            result.append(fields[0])
    return result

print(hidden_roots(["root:x:0:0::/root:/bin/bash", "bk:x:0:0::/b:/bin/sh"]))

