fn step_score(n: i32) -> i32 {
    let mut total = 0;
    for i in 1..=n {
        if i % 3 == 0 {
            total += i * 2;
        } else if i % 2 == 0 {
            continue;
        } else {
            total += i;
        }
    }
    total
}

