questions.solution:
fn eval_bonus(sum: i32, count: i32, bonus: bool) -> i32 {
    if count <= 0 {
        return 0;
    }
    let avg = (sum as f64) / (count as f64);
    let base = if avg >= 90.0 {
        3
    } else if avg >= 70.0 {
        2
    } else {
        1
    };
    if bonus { base + 1 } else { base }
}

fn main() {
    println!("{}", eval_bonus(270, 3, true));
    println!("{}", eval_bonus(140, 2, false));
}

