trait Reportable {
    fn summary(&self) -> String;
}

struct Record {
    name: String,
    score: i32,
}

impl Reportable for Record {
    fn summary(&self) -> String {
        format!("{}({})", self.name, self.score)
    }
}

fn parse_line(line: &str) -> Result<Record, String> {
    let (name, raw) = line.split_once(':').ok_or_else(|| String::from("invalid"))?;
    let score = raw.trim().parse::<i32>().map_err(|_| String::from("invalid"))?;
    Ok(Record { name: String::from(name.trim()), score })
}

fn best_record(lines: &[&str]) -> Result<String, String> {
    if lines.is_empty() {
        return Err(String::from("invalid"));
    }
    let mut records = Vec::new();
    for line in lines {
        records.push(parse_line(line)?);
    }
    records.sort_by(|a, b| b.score.cmp(&a.score).then_with(|| a.name.cmp(&b.name)));
    Ok(records[0].summary())
}

fn main() {
    println!("{:?}", best_record(&["jiwoo:90", "gayoung:95", "minsu:95"]));
}

