fn fib_memo(n: usize, memo: &mut Vec<i64>) -> i64 {
    if n <= 1 { return n as i64; }
    if memo[n] != -1 { return memo[n]; }
    let val = fib_memo(n - 1, memo) + fib_memo(n - 2, memo);
    memo[n] = val;
    val
}

fn main() {
    let mut memo = vec![-1_i64; 11];
    println!("{}", fib_memo(10, &mut memo));
}

fn min_coins(amount: usize, coins: &[usize]) -> i32 {
    let inf = 1_000_000;
    let mut dp = vec![inf; amount + 1];
    dp[0] = 0;
    for a in 1..=amount {
        for &c in coins {
            if a >= c {
                dp[a] = dp[a].min(dp[a - c] + 1);
            }
        }
    }
    if dp[amount] >= inf { -1 } else { dp[amount] }
}

