use std::cell::RefCell;
use std::rc::Rc;

struct Node {
    val: i32,
    next: Option<Box<Node>>,
}

fn sum_list(head: &Option<Box<Node>>) -> i32 {
    let mut total = 0;
    let mut cur = head;
    while let Some(node) = cur {
        total += node.val;
        cur = &node.next;
    }
    total
}

fn main() {
    let head = Some(Box::new(Node {
        val: 10,
        next: Some(Box::new(Node {
            val: 20,
            next: Some(Box::new(Node { val: 30, next: None })),
        })),
    }));
    let total = sum_list(&head);
    println!("{}", total);
    let shared = Rc::new(RefCell::new(Vec::new()));
    let w1 = Rc::clone(&shared);
    let w2 = Rc::clone(&shared);
    w1.borrow_mut().push(total);
    w2.borrow_mut().push(100);
    println!("{:?}", shared.borrow());
}

