fn max_window(nums: &[i32], k: usize) -> i32 {
    let mut win: i32 = nums[..k].iter().sum();
    let mut best = win;
    for i in k..nums.len() {
        win += nums[i] - nums[i - k];
        best = best.max(win);
    }
    best
}

