def filter_stock(names, counts, blocked):
    blocked_set = set(blocked)
    return {
        name: count
        for name, count in zip(names, counts)
        if name not in blocked_set and count > 0
    }

print(filter_stock(["사과", "우유", "빵"], [4, 0, 3], ["빵"]))

