class Account:
    def __init__(self, balance=0):
        self.balance = balance
    def deposit(self, amount):
        self.balance += amount

class RewardAccount(Account):
    def __init__(self, balance=0):
        super().__init__(balance)
    def deposit_all(self, *amounts):
        for amt in amounts:
            if amt > 0:
                self.deposit(amt + amt // 10)

def simulate_reward(initial, deposits):
    acc = RewardAccount(initial)
    acc.deposit_all(*deposits)
    return acc.balance

