def network_address(ip, prefix):
    n = 0
    for part in ip.split("."):
        n = (n << 8) | int(part)
    mask = (0xFFFFFFFF << (32 - prefix)) & 0xFFFFFFFF
    n &= mask
    return ".".join(str((n >> s) & 255) for s in (24, 16, 8, 0))

print(network_address("192.168.1.130", 26))

