import re

def brute_force_ips(lines, limit):
    count = {}
    for line in lines:
        m = re.search(r"Failed password .*?from (\S+)", line)
        if m:
            count[m.group(1)] = count.get(m.group(1), 0) + 1
    return sorted(ip for ip, n in count.items() if n >= limit)

print(brute_force_ips(["Failed password for a from 203.0.113.9 port 1"] * 3, 3))

