questions.solution:
fn min_max(nums: &[i32]) -> (i32, i32) {
    let mut lo = nums[0];
    let mut hi = nums[0];
    for &v in nums {
        if v < lo { lo = v; }
        if v > hi { hi = v; }
    }
    (lo, hi)
}

fn main() {
    let data = [4, 9, 2, 7];
    let (lo, hi) = min_max(&data);
    println!("{} {}", lo, hi);
}

