use std::fs;

fn main() {
    let raw = fs::read_to_string("orders.txt").expect("orders.txt 읽기 실패");
    let mut total = 0;
    for line in raw.lines() {
        let cols: Vec<&str> = line.split(',').collect();
        if cols.len() == 3 {
            let qty: i32 = cols[1].trim().parse().unwrap_or(0);
            let price: i32 = cols[2].trim().parse().unwrap_or(0);
            total += qty * price;
        }
    }
