fn min_coins(amount: usize, coins: &[usize]) -> i32 {
    let inf = 1_000_000;
    let mut dp = vec![inf; amount + 1];
    dp[0] = 0;
    for a in 1..=amount {
        for &c in coins {
            if a >= c {
                dp[a] = dp[a].min(dp[a - c] + 1);
            }
        }
    }
    if dp[amount] >= inf { -1 } else { dp[amount] }
}

