fn is_valid(s: &str) -> bool {
    let mut st = Vec::new();
    for ch in s.chars() {
        match ch {
            '(' => st.push(')'),
            '[' => st.push(']'),
            '{' => st.push('}'),
            ')' | ']' | '}' => {
                if st.pop() != Some(ch) { return false; }
            }
            _ => {}
        }
    }
    st.is_empty()
}

