use std::collections::VecDeque;

fn grid_min_steps(rows: usize, cols: usize, flat: &[i32]) -> i32 {
    if rows == 0 || cols == 0 || flat.len() < rows * cols {
        return -1;
    }
    if flat[0] == 1 || flat[rows * cols - 1] == 1 {
        return -1;
    }
    let mut dist = vec![-1; rows * cols];
    let mut q = VecDeque::new();
    dist[0] = 0;
    q.push_back((0usize, 0usize));
    let dirs = [(-1isize, 0isize), (1, 0), (0, -1), (0, 1)];
    while let Some((r, c)) = q.pop_front() {
        let cur = dist[r * cols + c];
        if r == rows - 1 && c == cols - 1 {
            return cur;
        }
        for (dr, dc) in dirs {
            let nr = r as isize + dr;
            let nc = c as isize + dc;
            if nr >= 0 && nr < rows as isize && nc >= 0 && nc < cols as isize {
                let idx = (nr as usize) * cols + (nc as usize);
                if flat[idx] == 0 && dist[idx] == -1 {
                    dist[idx] = cur + 1;
                    q.push_back((nr as usize, nc as usize));
                }
            }
        }
    }
    -1
}

fn main() {
    let g = [0, 0, 1, 1, 0, 0, 0, 0, 0];
    println!("{}", grid_min_steps(3, 3, &g));
}

