use std::collections::VecDeque;

fn main() {
    let map = ["S#.", ".#.", "..E"];
    let g: Vec<Vec<char>> = map.iter().map(|s| s.chars().collect()).collect();
    let mut dist = vec![vec![-1; 3]; 3];
    let mut q = VecDeque::from([(0usize, 0usize)]);
    dist[0][0] = 0;
    while let Some((r, c)) = q.pop_front() {
        for (dr, dc) in [(-1isize,0),(1,0),(0,-1),(0,1)] {
            if let (Some(nr), Some(nc)) = (r.checked_add_signed(dr), c.checked_add_signed(dc)) {
                if nr < 3 && nc < 3 && g[nr][nc] != '#' && dist[nr][nc] == -1 {
                    dist[nr][nc] = dist[r][c] + 1;
                    q.push_back((nr, nc));
                }
            }
        }
    }
