use std::collections::BTreeMap;
use std::fs;

fn main() {
    let raw = fs::read_to_string("sales.csv").expect("sales.csv 읽기 실패");
    let mut totals: BTreeMap<&str, i32> = BTreeMap::new();
    let mut grand_total = 0;
    for line in raw.lines().skip(1) {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let cols: Vec<&str> = line.split(',').collect();
        if cols.len() == 3 {
            let qty: i32 = cols[1].trim().parse().unwrap_or(0);
            let price: i32 = cols[2].trim().parse().unwrap_or(0);
            let amt = qty * price;
            *totals.entry(cols[0].trim()).or_insert(0) += amt;
            grand_total += amt;
        }
    }
    let report: Vec<String> = totals.into_iter().map(|(k, v)| format!("{}:{}", k, v)).collect();
    fs::write("report.txt", report.join("\n")).expect("report.txt 쓰기 실패");
    println!("{}", grand_total);
}

