use std::collections::BTreeMap;
use std::fs;

fn main() {
    let raw = fs::read_to_string("server.log").expect("server.log 읽기 실패");
    let mut total = 0;
    let mut codes: BTreeMap<&str, usize> = BTreeMap::new();
    for raw_line in raw.lines() {
        let line = raw_line.trim();
        if line.starts_with("[ERROR]") {
            if let Some(code) = line.split_whitespace().nth(1) {
                total += 1;
                *codes.entry(code).or_insert(0) += 1;
            }
        }
    }
    let mut fields = vec![format!("\"error_count\": {}", total)];
    for (k, v) in &codes {
        fields.push(format!("\"{}\": {}", k, v));
    }
    let json_text = format!("{{{}}}", fields.join(", "));
    fs::write("audit.json", json_text).expect("audit.json 쓰기 실패");
    println!("errors={}", total);
}

