from collections import deque

def max_zone_area(grid):
    if not grid or not grid[0]:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    best = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not visited[r][c]:
                q = deque([(r, c)])
                visited[r][c] = True
                area = 0
                while q:
                    cr, cc = q.popleft()
                    area += 1
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1 and not visited[nr][nc]:
                            visited[nr][nc] = True
                            q.append((nr, nc))
                if area > best:
                    best = area
    return best

print(max_zone_area([[1, 1, 0, 0], [1, 0, 0, 1], [0, 0, 1, 1]]))

def min_ship_capacity(weights, days):
    if not weights:
        return 0
    lo, hi = max(weights), sum(weights)
    while lo < hi:
        mid = (lo + hi) // 2
        used, cur = 1, 0
        for w in weights:
            if cur + w > mid:
                used += 1
                cur = 0
            cur += w
        if used <= days:
            hi = mid
        else:
            lo = mid + 1
    return lo

