questions.solution:
use std::collections::HashMap;

fn top_item(logs: &[&str]) -> String {
    let mut counts: HashMap<&str, i32> = HashMap::new();
    for line in logs {
        if let Some((name, raw)) = line.split_once(':') {
            if let Ok(qty) = raw.trim().parse::<i32>() {
                if qty > 0 {
                    *counts.entry(name.trim()).or_insert(0) += qty;
                }
            }
        }
    }
    let mut best: Option<(&str, i32)> = None;
    for (name, total) in counts {
        best = Some(match best {
            None => (name, total),
            Some((bn, bt)) if total > bt || (total == bt && name < bn) => (name, total),
            Some(prev) => prev,
        });
    }
    best.map(|(name, _)| String::from(name)).unwrap_or_else(|| String::from("none"))
}

fn main() {
    println!("{}", top_item(&["pear:4", "apple:2", "apple:3", "bad"]));
}

