struct BankAccount {
    balance: i32,
}

impl BankAccount {
    fn new(initial: i32) -> Self {
        Self { balance: initial }
    }
    fn deposit(&mut self, amount: i32) {
        self.balance += amount;
    }
    fn withdraw(&mut self, amount: i32) -> bool {
        if self.balance >= amount {
            self.balance -= amount;
            true
        } else {
            false
        }
    }
}

fn main() {
    let mut acc = BankAccount::new(100);
    acc.deposit(50);
    println!("{} {}", acc.withdraw(20), acc.balance);
