fn compress_str(s: &str) -> String {
    let mut chars = s.chars();
    let mut prev = match chars.next() {
        Some(c) => c,
        None => return String::new(),
    };
    let mut cnt = 1;
    let mut out = String::new();
    for ch in chars {
        if ch == prev {
            cnt += 1;
        } else {
            out.push_str(&format!("{}{}", prev, cnt));
            prev = ch;
            cnt = 1;
        }
    }
    out.push_str(&format!("{}{}", prev, cnt));
    out
}

fn main() {
    println!("{}", compress_str("aaabbcccc"));
}

