use std::collections::VecDeque;

fn printer_order(priorities: &[i32], target: usize) -> usize {
    let mut q: VecDeque<(usize, i32)> = priorities.iter().copied().enumerate().collect();
    let mut order = 0;
    while let Some(cur) = q.pop_front() {
        if q.iter().any(|&x| x.1 > cur.1) {
            q.push_back(cur);
        } else {
            order += 1;
            if cur.0 == target {
                return order;
            }
        }
    }
    order
}

fn main() {
    println!("{}", printer_order(&[2, 1, 3, 2], 2));
