use std::collections::HashMap;
use std::io::{self, Read};

struct Record {
    name: String,
    dept: String,
    score: i32,
}

fn main() {
    let mut buf = String::new();
    io::stdin().read_to_string(&mut buf).unwrap();
    let mut records: Vec<Record> = Vec::new();
    let mut dept_stats: HashMap<String, (i32, i32)> = HashMap::new();
    for line in buf.lines() {
        let p: Vec<&str> = line.split_whitespace().collect();
        if p.len() == 3 {
            if let Ok(score) = p[2].parse::<i32>() {
                let e = dept_stats.entry(p[1].to_string()).or_insert((0, 0));
                e.0 += score;
                e.1 += 1;
                records.push(Record { name: p[0].to_string(), dept: p[1].to_string(), score });
            }
        }
    }
    let mut dept_avgs: Vec<(String, i32)> = dept_stats
        .into_iter()
        .map(|(d, (sum, cnt))| (d, sum / cnt))
        .collect();
    dept_avgs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    records.sort_by(|a, b| b.score.cmp(&a.score).then_with(|| a.name.cmp(&b.name)));
    if !dept_avgs.is_empty() && !records.is_empty() {
        println!("top_dept={} best={}({})", dept_avgs[0].0, records[0].name, records[0].score);
    }
}

