use std::collections::BTreeMap;
use std::io::{self, Read};

fn main() {
    let mut buf = String::new();
    io::stdin().read_to_string(&mut buf).unwrap();
    let mut balances: BTreeMap<String, i32> = BTreeMap::new();
    let mut rejected = 0;
    for line in buf.lines() {
        let p: Vec<&str> = line.split_whitespace().collect();
        match p.as_slice() {
            ["DEPOSIT", name, amt_s] => {
                if let Ok(amt) = amt_s.parse::<i32>() {
                    if amt <= 0 { continue; }
                    *balances.entry((*name).to_string()).or_insert(0) += amt;
                }
            }
            ["WITHDRAW", name, amt_s] => {
                if let Ok(amt) = amt_s.parse::<i32>() {
                    if amt <= 0 { continue; }
                    let cur = *balances.get(*name).unwrap_or(&0);
                    if cur >= amt {
                        *balances.get_mut(*name).unwrap() -= amt;
                    } else {
                        rejected += 1;
                    }
                }
            }
            ["TRANSFER", from, to, amt_s] => {
                if let Ok(amt) = amt_s.parse::<i32>() {
                    if amt <= 0 { continue; }
                    let cur = *balances.get(*from).unwrap_or(&0);
                    if cur >= amt {
                        *balances.get_mut(*from).unwrap() -= amt;
                        *balances.entry((*to).to_string()).or_insert(0) += amt;
                    } else {
                        rejected += 1;
                    }
                }
            }
            _ => {}
        }
    }
    for (name, bal) in &balances {
        println!("{}={}", name, bal);
    }
    println!("rejected={}", rejected);
}

