// 1) Bottom-Up DP 테이블로 계단 오르기  2) Vec 스택으로 괄호 유효성 검사
fn climb_stairs(n: usize) -> i64 {
    let mut dp = vec![1_i64; n + 1];
    for i in 2..=n { dp[i] = dp[i - 1] + dp[i - 2]; }
    dp[n]
}

fn is_balanced(s: &str) -> bool {
    let mut st = Vec::new();
    for c in s.chars() {
        match c {
            '(' => st.push(')'), '[' => st.push(']'), '{' => st.push('}'),
            ')' | ']' | '}' => if st.pop() != Some(c) { return false; },
            _ => {}
        }
    }
    st.is_empty()
}

fn main() {
